 import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import './QuestionDetails.css';
import HomeIcon from '../Common/HomeIcon';
import AnswerForm from '../Answers/AnswerForm';
import { getQuestionById, getAnswersByQuestionId, deleteAnswer } from '../../services/api'; // Importă deleteAnswer

function QuestionDetails() {
  const { id } = useParams();
  const [question, setQuestion] = useState(null);
  const [answers, setAnswers] = useState([]);
  const [likes, setLikes] = useState(0);
  const [currentUserId, setCurrentUserId] = useState(null); // Stare pentru ID-ul utilizatorului curent

  useEffect(() => {
    // Obține ID-ul utilizatorului logat de la localStorage
    const userData = JSON.parse(localStorage.getItem('token')); // Presupunând că user data e stocată ca JSON cu cheia 'token' și include 'userId'
    if (userData && userData.userId) {
        setCurrentUserId(userData.userId);
    } else {
        // Dacă nu găsește user data sau userId, setează la null (utilizator nelogat sau data incompletă)
        setCurrentUserId(null);
    }


    // Question details
    getQuestionById(id)
      .then(data => {
        setQuestion(data);
        setLikes(data.likes || 0);
      })
      .catch(err => console.error('Eroare la încărcarea întrebării:', err));

    // Answers
    getAnswersByQuestionId(id)
      .then(data => setAnswers(data))
      .catch(err => console.error('Eroare la încărcarea răspunsurilor:', err));
  }, [id]);

  const handleVote = type => {
    setLikes(prev => prev + (type === 'like' ? 1 : -1));
  };

  // Handler pentru ștergerea unui răspuns
  const handleDeleteAnswer = async (answerId) => {
    if (window.confirm('Sigur doriți să ștergeți acest răspuns?')) {
      try {
        // Apelăm funcția API de ștergere
        const result = await deleteAnswer(answerId, currentUserId); // Trimitem ID-ul răspunsului și ID-ul utilizatorului
        console.log(result.message); // Afișăm mesajul de succes/eroare de la backend

        // Dacă ștergerea a avut succes pe backend, actualizăm starea locală
        if (result.message === "Answer deleted successfully.") {
            setAnswers(prevAnswers => prevAnswers.filter(answer => answer.id !== answerId));
        } else {
             alert('Nu s-a putut șterge răspunsul: ' + result.message);
        }

      } catch (error) {
        alert('A apărut o eroare la ștergerea răspunsului.');
        console.error('Eroare deleteAnswer:', error);
      }
    }
  };


  if (!question) {
    return <p>Se încarcă...</p>;
  }

  return (
    <div className="question-details-container">
      <HomeIcon />

      <h2>{question.title}</h2>
      <p><strong>Autor:</strong> {question.user?.username || 'Anonim'}</p>
      <p><strong>Data:</strong> {question.date}</p>
      <p><strong>Conținut:</strong> {question.text}</p>

      <p>
        <strong>Etichete:</strong>{' '}
        {(question.questionTags || []).map(qt =>
          <span className="tag" key={qt.id}>{qt.tag.name}</span>
        )}
      </p>

      <div className="like-buttons">
        <button onClick={() => handleVote('like')}>👍</button>
        <button onClick={() => handleVote('dislike')}>👎</button>
        <span>{likes} voturi</span>
      </div>

      <h3>Răspunsuri:</h3>

      {answers.length === 0 ? (
        <p><i>Încă nu există răspunsuri pentru această întrebare.</i></p>
      ) : (
        <ul>
          {answers.map(answer => (
            <li key={answer.id}>
              <p>{answer.text}</p>
              <p style={{ fontSize: '0.85em', color: '#666' }}>
                — {answer.user?.username || 'Utilizator necunoscut'}
                {/* Afișează butonul Șterge doar dacă utilizatorul curent este autorul răspunsului */}
                {currentUserId !== null && answer.user?.id === currentUserId && (
                    <button
                        onClick={() => handleDeleteAnswer(answer.id)}
                        style={{ marginLeft: '10px', fontSize: '0.8em', cursor: 'pointer' }}
                    >
                        Șterge
                    </button>
                )}
              </p>
            </li>
          ))}
        </ul>
      )}

      {/* Presupunem că AnswerForm ar trebui să fie vizibil doar dacă utilizatorul este logat */}
      {currentUserId && (
           <AnswerForm
                questionId={id}
                onAnswerSubmitted={newAnswer => setAnswers(prev => [...prev, newAnswer])}
            />
      )}

    </div>
  );
}

export default QuestionDetails;
